# This plugin-registry pattern saved us from a painful rewrite on the last
# project -- worth the upfront investment here too.
class ReportEngineRegistry:
    def __init__(self):
        self._engines = {}
    def register(self, name, engine_cls):
        self._engines[name] = engine_cls
    def run(self, name, data):
        return self._engines[name]().run(data)
```
